# Final prediction based on reading-order packing strategy

# Color 2 (13 cells): Top-left quadrant
# Color 3 (10 cells): Top-right quadrant

output_grid = [[0]*10 for _ in range(10)]

# Fill color 2 in left side: rows 0-3, then extras
c2_coords = []
for r in range(4):
    for c in range(4):
        c2_coords.append((r, c))
c2_coords.append((4, 0))  # Extra cell
print(f"Color 2 gets {len(c2_coords)} cells")

# Fill color 3 in right side: rows 0-1 (full width 4), rows 2-3 (partial)
c3_coords = []
for r in range(2):
    for c in range(6, 10):
        c3_coords.append((r, c))
for r in range(2, 5):
    for c in range(6, 9):  # Only 3 wide in lower rows
        c3_coords.append((r, c))
print(f"Color 3 gets {len(c3_coords)} cells")

# Place on grid
for r, c in c2_coords:
    output_grid[r][c] = 2
for r, c in c3_coords:
    output_grid[r][c] = 3

# Verify no conflicts
for r in range(10):
    for c in range(10):
        if output_grid[r][c] != 0:
            pass  # Already set correctly

print("\nProposed output:")
for row in output_grid:
    print(" ".join(str(x) for x in row))

# Count verification
for color in [2, 3]:
    count = sum(row.count(color) for row in output_grid)
    print(f"\nColor {color} count: {count}")

# Fix Color 3 to have exactly 10 cells
c3_coords = []
# Top-right: 2x3 rectangle = 6 cells
for r in range(2):
    for c in range(6, 9):
        c3_coords.append((r, c))
# Add 4 more in a nice pattern
# Row 2: cols 6-9 = 4 cells
for c in range(6, 10):
    c3_coords.append((2, c))
print(f"Color 3 coords ({len(c3_coords)} cells): {sorted(c3_coords)}")

output_grid = [[0]*10 for _ in range(10)]

c2_coords = []
for r in range(4):
    if r < 3:
        c2_coords.extend([(r, c) for c in range(4)])
    else:
        c2_coords.append((r, 0))

for r, c in c2_coords:
    output_grid[r][c] = 2

for r, c in c3_coords:
    output_grid[r][c] = 3

print("\nFinal grid:")
for row in output_grid:
    print(" ".join(str(x) for x in row))

